-- COS 101 Exam Sprint: import 200 curated MCQs into an empty private bank
-- Sources: supplied COS 101 lecture note plus clearly labelled General COS 101 enrichment
-- The script creates a bank if none exists and refuses to overwrite existing questions.
BEGIN;

DO $import$
DECLARE
  v_set_id uuid;
  v_set_count integer;
  v_question jsonb;
  v_option jsonb;
BEGIN
  SELECT count(*) INTO v_set_count
  FROM public.study_quiz_sets
  WHERE upper(regexp_replace(coalesce(course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'COS101'
    AND delivery_mode = 'mock_exam'
    AND exam_campaign_key = 'supplementary-2026';

  IF v_set_count = 0 THEN
    INSERT INTO public.study_quiz_sets
      (title, description, course_code, level, semester, difficulty, time_limit_minutes,
       questions_count, published, visibility, source, delivery_mode, exam_campaign_key,
       access_tier, exam_question_count, diagnostic_question_count, diagnostic_time_limit_minutes)
    VALUES
      ('COS 101 Exam Sprint Mock',
       'Private COS 101 bank covering the supplied Introduction to Computing Sciences note and modern computing foundations.',
       'COS 101', '100', 'first', 'hard', 40,
       0, false, 'private', 'exam_sprint', 'mock_exam', 'supplementary-2026',
       'plus_monthly', 40, 10, 10)
    RETURNING id INTO v_set_id;
  ELSIF v_set_count = 1 THEN
    SELECT id INTO v_set_id
    FROM public.study_quiz_sets
    WHERE upper(regexp_replace(coalesce(course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'COS101'
      AND delivery_mode = 'mock_exam'
      AND exam_campaign_key = 'supplementary-2026'
    LIMIT 1;
  ELSE
    RAISE EXCEPTION 'More than one COS 101 Exam Sprint bank exists. Keep one target bank before importing.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.study_quiz_questions
    WHERE coalesce(set_id, quiz_set_id) = v_set_id
  ) THEN
    RAISE EXCEPTION 'The COS 101 target bank already contains questions. Import stopped to prevent duplicates.';
  END IF;

  FOR v_question IN
    SELECT value FROM jsonb_array_elements($cos101_questions$[{"id":"9d2a50bb-8fac-5ddf-925f-f53e9fe45049","position":0,"prompt":"Which sequence correctly represents the basic information-processing cycle of a computer?","explanation":"A computer accepts input, processes it under program control and produces output.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"History, Generations and Classification of Computers","fingerprint":"413197f187da04757d4bf265cc42c5cd5de2bb460b930196987e273470fad835","studyRef":{"sourceLabel":"COS 101 lecture note, Module One","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module One","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"ed2ebfde-76c2-5386-88a7-73376d0584d4","text":"Input, processing, output","isCorrect":true,"position":0},{"id":"8602e0aa-633f-57d1-bb60-364d328155a8","text":"Output, input, storage only","isCorrect":false,"position":1},{"id":"ae69b254-7499-5d4b-9c1a-1bfd1c2f9e70","text":"Processing, output, input","isCorrect":false,"position":2},{"id":"7ab84e32-b970-51ba-a2bd-e2a2ae74523d","text":"Input, output, processing","isCorrect":false,"position":3}]},{"id":"8329d2fb-6502-5738-9ddd-31efb7e27358","position":1,"prompt":"What does data mean in the lecture note?","explanation":"Data are raw representations that can be processed to produce information.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"History, Generations and Classification of Computers","fingerprint":"863a8b755cb013d3d0b7d7e5ec9f0861a0dae82f0339b64bfdba97226bdb2788","studyRef":{"sourceLabel":"COS 101 lecture note, Module One","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module One","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true