ce case","isCorrect":false,"position":1},{"id":"167647d1-e3b5-52f4-8721-e7e13851ee93","text":"The user's handwriting","isCorrect":false,"position":2},{"id":"1b2ced14-2fed-5046-a32a-f24d23d4afe4","text":"The number of paper files nearby","isCorrect":false,"position":3}]},{"id":"8d2e9609-314d-5506-89da-db10cd28116d","position":89,"prompt":"A document created in one application opens with broken formatting in another. What is the likely issue?","explanation":"Different applications may interpret proprietary or complex file features differently.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Computer Applications and Platforms","fingerprint":"ba143fe350261366e6a46ce34c545510e989583fc3db02303ae13b9aa3843cba","studyRef":{"sourceLabel":"COS 101 lecture note, Module Four","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Four","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"112ec89c-7350-58ba-a3d0-986b453b8018","text":"The keyboard entered only binary","isCorrect":false,"position":0},{"id":"f92cce93-a447-547a-b6af-a1b13030f90d","text":"The CPU became an output device","isCorrect":false,"position":1},{"id":"500392f7-f75f-5d84-9dda-a401f305a438","text":"The internet changed the author","isCorrect":false,"position":2},{"id":"ca5c2592-f2b9-5f22-9eb4-bf1c702d45d3","text":"Incomplete file-format compatibility","isCorrect":true,"position":3}]},{"id":"50a9c34a-aa52-588f-b0fa-bb03f8e84bb2","position":90,"prompt":"Which application category is most appropriate for organizing related customer records and queries?","explanation":"Database software structures records and supports efficient searching, updating and reporting.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Computer Applications and Platforms","fingerprint":"00b6aa9e3c50bf7a4af198a728a7dd7c8f1e