oftware","isCorrect":false,"position":3}]},{"id":"7428061f-2a2a-5e67-a6c8-d4f5fd2970dc","position":92,"prompt":"A banking app requests access to contacts, microphone and location even though none is needed for a transfer. What is the best security response?","explanation":"Applications should receive only permissions required for their legitimate functions.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Computer Applications and Platforms","fingerprint":"90bf480e0a54e99fb6a9a51e4908fbe22c77f7c04bf429385a2253e2d5bf4f21","studyRef":{"sourceLabel":"COS 101 lecture note, Module Four","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Four","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"f35a99bd-8960-54ea-bdf0-f5765a89d755","text":"Deny unnecessary permissions and review whether the app is trustworthy","isCorrect":true,"position":0},{"id":"6189a4f4-fdda-5792-87bf-08c091d730f5","text":"Grant every request automatically","isCorrect":false,"position":1},{"id":"9f2027b7-fb4c-515e-8f33-8cec197052e7","text":"Publish the login password","isCorrect":false,"position":2},{"id":"a3a364c0-6703-5fa4-b946-84358607ef81","text":"Disable transaction encryption","isCorrect":false,"position":3}]},{"id":"e43f2ff8-9612-5ebb-a714-85ab6016f673","position":93,"prompt":"A web application must work during unstable connectivity and synchronize later. Which design is most suitable?","explanation":"Offline-capable web design can preserve essential functions and reconcile data when connectivity returns.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Computer Applications and Platforms","fingerprint":"f61ad4a49ee1ff6d69d325e2e51edc2fb4e1a7250c431dddba13845dc32cc112","studyRef":{"sourceLabel":"COS 101 lecture note, Module Four","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Four","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"792e8d38-888c-5b9d-b23c-0aff887746e6","text":"Require a fresh download for every click","isCorrect":false,"position":0},{"id":"169631ff-bddd-5705-b0ab-5df05de55c43","text":"Store all state only in volatile server memory","isCorrect":false,"position":1},{"id":"312601ea-b1b3-5954-bd23-5752bd18bd73","text":"Remove every offline action","isCorrect":false,"position":2},{"id":"817eb571-ec8e-5418-abd9-a717fa1af9d2","text":"Cache required resources locally and queue changes for later synchronization","isCorrect":true,"position":3}]},{"id":"865723ee-055b-5e6f-8973-d2f85955c94d","position":94,"prompt":"A team chooses between a native and web application for a graphics tool requiring intensive device integration. Which consideration is strongest?","explanation":"Architecture should follow workload, hardware integration, distribution and maintenance needs.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Computer Applications and Platforms","fingerprint":"bd985e38e295eeb45652606529437078a234eec643fec5e1126f7cd0d672bb31","studyRef":{"sourceLabel":"COS 101 lecture note, Module Four","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Four","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"21b3d091-f586-5f89-a6c0-e54dfa8941b0","text":"The number of users' paper notebooks","isCorrect":false,"position":0},{"id":"b7dee1ef-4456-5912-9590-992cc6c083ac","text":"Whether the app title is short","isCorrect":false,"position":1},{"id":"89d3e6da-f138-5e8e-9537-00d86d1e4581","text":"Required performance, hardware access and supported platforms","isCorrect":true,"position":2},{"id":"bd1f14d4-fc83-568a-9a0b-12b9147e9