:"COS 101 lecture note, Module Five","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"f53d2700-b179-5880-842b-bcf2bcf1d914","text":"Accessing previously stored information when it is needed","isCorrect":true,"position":0},{"id":"9b3fd203-874f-53af-8e94-1ab6ed398c8f","text":"Deleting the only available copy","isCorrect":false,"position":1},{"id":"b7c3f12e-466c-58bf-a17d-4705a60bd4d6","text":"Changing hardware into software","isCorrect":false,"position":2},{"id":"990ec600-b3ed-5d17-9a9b-dace1db84e0f","text":"Creating a random result","isCorrect":false,"position":3}]},{"id":"d632c0ec-13e1-5c52-ad35-e3952574cb07","position":105,"prompt":"Which form can be used to display information to a person?","explanation":"Human-oriented information can be presented through visual, printed and audible media.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Information Processing and Society","fingerprint":"299c44db8e2e6bf4203553ab8f3d139fe0c78fbddba6939822e966dc50401afe","studyRef":{"sourceLabel":"COS 101 lecture note, Module Five","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Five","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"d02e7613-8845-50f2-8736-fb88b233817a","text":"Only binary voltage hidden inside a CPU","isCorrect":false,"position":0},{"id":"eeb0849d-8c2b-525c-8a33-3734b7980792","text":"Only punched cards","isCorrect":false,"position":1},{"id":"c3f9d1c9-2660-56fe-9654-944d1ec27766","text":"Only handwritten numbers","isCorrect":false,"position":2},{"id":"eeb70e2d-fc6c-5ff1-8938-3316a5223af8","text":"Text, image, sound or video","isCorrect":true,"position":3}]},{"id":"1efcabf0-29ca-54fc-a22a-2f85022e1254","position":106,"prompt":"What is a central goal of information management?","explanation":"Information management organizes, protects and delivers information to support work and decisions.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Information Processing and Society","fingerprint":"63c532dd036ddd1d2f53400a729ff6a52872e13952fdc4ba2d5aa983ba2d704a","studyRef":{"sourceLabel":"COS 101 lecture note, Module Five","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Five","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"664ec31a-7a20-5402-8d2a-709046a41a11","text":"Keeping all information without organization","isCorrect":false,"position":0},{"id":"aada4c0c-a0a2-51f3-a19c-77eb0f956d52","text":"Replacing every decision with guesswork","isCorrect":false,"position":1},{"id":"3dfe31ce-0229-54d2-85ae-d51faa8d2962","text":"Making reliable information available where and when it is needed","isCorrect":true,"position":2},{"id":"5696679b-5664-534f-a5eb-199cfc9de978","text":"Preventing every authorized user from access","isCorrect":false,"position":3}]},{"id":"5d6c2b8f-540b-5fe6-ad1d-e4124ffa2bd4","position":107,"prompt":"What does information dissemination involve?","explanation":"Dissemination communicates information through appropriate channels and formats.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Information Processing and Society","fingerprint":"a43e93d7b478f32fc759180b86eb9fc1c66f46b62259eb8b2b5ec8d1ade3a84b","studyRef":{"sourceLabel":"COS 101 lecture note, Module Five","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Five","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"fbd7fbd8-93a7-5d49-8691-05f846c612f8","text":"Removing context from all data","isCorrect":false,"position":0},{"id":"cdc4b772-b539-5b85-b1e0-b70afe3dc6e0","text":"Distributing information to intended recipients","isCorrect":true,"position":1},{"id":"741a9b22-33b8-5b5e-927a-ffd854ea5bb9","text":"Keeping every record isolated forever","isCorrect":false,"position":2},{"id":"2e527c71-2403-5ad4-a396-23d806101fc1","text":"Converting a computer into a printer","isCorrect":false,"position":3}]},{"id":"077a23ff-a1af-5c45-89db-744099c4e947","position":108,"prompt":"Why does placing raw data in context make it more useful?","explanation":"Meaning emerges when values are related to their source, purpose, time and other relevant facts.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Information Processing and Society","fingerprint":"d1e7b5cfe4e19ec0166aa79ee2607b50d8edf0fd2bfac8b15d1865687390438b","studyRef":{"sourceLabel":"COS 101 lecture note, Module Five","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Five","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"98ec7e77-904a-55b9-a3a6-a7ce0398b7e7","text":"Context helps users interpret its meaning and relevance","isCorrect":true,"position":0},{"id":"ad3b6ee8-ce69-57b6-ba7a-2bc89fdf4b61","text":"Context removes every relationship","isCorrect":false,"position":1},{"id":"41ee95f7-fc5f-56d6-8b4f-7c297d860db0","text":"Raw data is always self-explanatory","isCorrect":false,"position":2},{"id":"c6489557-c534-590b-a6b5-dd5521f1d62a","text":"Context prevents analysis","isCorrect":false,"position":3}]},{"id":"06fc8220-f449-58a6-ab5e-48fcbbbaa7af","position":109,"prompt":"What does real-time information management emphasize?","explanation":"Real-time requirements are determined by how quickly information must reach the decision point.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Information Processing and Society","fingerprint":"0f8e765acdfaa134f9259c089c416ca3c667c4d6a60a515b408e12c5982a7