udyRef":{"sourceLabel":"General COS 101 enrichment: Information Processing and Society","sourceKind":"general_cos101","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"General COS 101 enrichment: Information Processing and Society","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a0c75a5c-7418-5041-801e-3d004b5febcd","text":"Data that describe another data item or resource","isCorrect":true,"position":0},{"id":"338b5d0d-8edd-5ae6-b233-c2b2d9ae6d1b","text":"A computer virus","isCorrect":false,"position":1},{"id":"a83bc1d2-7183-53f7-8ed1-7d6e9acc7aab","text":"A physical output device","isCorrect":false,"position":2},{"id":"04fa6a1e-83a3-57f6-8101-918288755317","text":"An electric current","isCorrect":false,"position":3}]},{"id":"6234e7cd-b65b-5dc8-b6b1-8038cec70e1f","position":121,"prompt":"How does data verification differ from validation?","explanation":"A value may be valid in format yet still differ from what the original source stated.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Information Processing and Society","fingerprint":"cce99e1834ad2a876cac6cb06d6b56931455dcd07a170136ee29ff9490821863","studyRef":{"sourceLabel":"General COS 101 enrichment: Information Processing and Society","sourceKind":"general_cos101","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"General COS 101 enrichment: Information Processing and Society","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"c7c17d54-e38a-5513-8778-d9d90092b4ce","text":"Verification deletes data while validation prints it","isCorrect":false,"position":0},{"id":"f31a4f64-7c3f-5ed8-8000-1bbd7bc22f7c","text":"They both guarantee future predictions","isCorrect":false,"position":1},{"id":"89ca11e5-3b80-576a-8ca7-1bfd8b8ba2d1","text":"Validation applies only to images","isCorrect":false,"position":2