ecture note, Module Six","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"4728fcfc-16bf-5404-810c-798cd936beca","text":"A domain name supplies complete evidence","isCorrect":false,"position":0},{"id":"e7945f3a-eddf-5833-97ab-c3378fca7dd4","text":"Online availability does not guarantee authority or accuracy","isCorrect":true,"position":1},{"id":"d0278642-c43d-5d33-b2da-bf445532dd8e","text":"Every website has passed academic peer review","isCorrect":false,"position":2},{"id":"d9ee24ba-8f7b-5c5f-8f68-244dfa8658d5","text":"Search ranking proves truth","isCorrect":false,"position":3}]},{"id":"551fbdd3-a8d7-5a57-8e43-f1fdeb2bcc7c","position":140,"prompt":"How can internet addiction affect a user?","explanation":"Compulsive use can interfere with daily functioning and wellbeing.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Internet Applications, Impact and Safety","fingerprint":"c9a467515b06c7f7a562780e9fb41c47ac76367d7a9dbe640fd867a52e6a9410","studyRef":{"sourceLabel":"COS 101 lecture note, Module Six","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Six","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"a770fb50-ad5b-5f95-a4ba-e0da527040fc","text":"It can disrupt health, responsibilities and relationships","isCorrect":true,"position":0},{"id":"ee05a2f8-15c0-5bc3-9480-1e5c3ec7bfe8","text":"It always improves sleep","isCorrect":false,"position":1},{"id":"34bdc951-1465-5c3b-825c-72ba21dde2b5","text":"It guarantees stronger offline communication","isCorrect":false,"position":2},{"id":"3c7177ec-67c2-5b90-b99b-8f7fad5b0c40","text":"It prevents anxiety","isCorrect":false,"position":3}]},{"id":"9f23e5c2-8c3c-53bd-90e6-8286c737df7e","position":141,"prompt":"Which risk is illustrated when criminals gain unauthorized access to an online account?","