ns":[{"id":"82a4d131-095a-5e2e-a5b3-75448af2d55f","text":"The classification of websites","isCorrect":false,"position":0},{"id":"59bf8206-7701-5214-8ba2-f8cb17108223","text":"The creation of paper-only files","isCorrect":false,"position":1},{"id":"590862a5-ef7b-5a01-852a-d090b6584db1","text":"A method of typing text","isCorrect":false,"position":2},{"id":"e8f5c4eb-a834-5014-b867-de7fb42a7e6e","text":"The design, construction and operation of machines that perform physical tasks","isCorrect":true,"position":3}]},{"id":"a83b986c-cdfc-5350-ada1-e772c8768e7d","position":182,"prompt":"What is the key idea behind edge computing?","explanation":"Local processing can reduce delay, bandwidth use and dependence on continuous connectivity.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"a42e650c74c87639af0fe29a0ce2ec428c8d233028d793d3d650b7e8abd3437e","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"70a72dd5-aa22-5746-9109-822f66a633dd","text":"Prevent local devices from computing","isCorrect":false,"position":0},{"id":"d49cfe8c-ad51-55c8-8f68-f960ea3c3375","text":"Use only one central keyboard","isCorrect":false,"position":1},{"id":"aaf9accf-a894-5058-914f-19fe9eb784c9","text":"Process data near where it is generated rather than sending everything to a distant centre","isCorrect":true,"position":2},{"id":"8b03f301-5415-54ad-a301-03508dd70731","text":"Store all data on the edge of a paper","isCorrect":false,"position":3}]},{"id":"f4c6e796-7e86-52cf-b49d-d2e44ac36b74","position":183,"prompt":"How can faster mobile networks support IoT deployments?","explanation":"Network improvements can support more responsive and numerous connected devices.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"ee409ee28cf090443b4386969f3fcfc07ac3c55598ccd242fd181c3c1b317515","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"59f1c36e-1a13-5d2a-9d2a-dd6d96125aa1","text":"They guarantee unlimited battery life","isCorrect":false,"position":0},{"id":"b831100e-0531-5aca-b6d9-b88141a62a54","text":"They can improve connectivity, capacity and response time for connected devices","isCorrect":true,"position":1},{"id":"aa085215-fce5-55bb-9000-fd973bd6b87c","text":"They remove the need for device security","isCorrect":false,"position":2},{"id":"889915d0-6f7f-51ec-bbb7-e22179f1473c","text":"They make sensors unnecessary","isCorrect":false,"position":3}]},{"id":"602205b8-133f-52a7-823f-fc8ebecd4248","position":184,"prompt":"Why might a company adopt cloud computing?","explanation":"Cloud services can shift infrastructure management and let capacity expand or contract with demand.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"dbba9cb4eba2c3585702868d20563e891e563fd45dbec2cfcd0258301ca58786","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"2e87c43c-f598-5413-ad59-90438db88613","text":"To scale resources without owning all underlying hardware","isCorrect":true,"position":0},{"id":"0aca5b83-9157-5804-8b41-1e8f2106977c","text":"To eliminate every operating cost","isCorrect":false,"position":1},{"id":"78e56f86-4460-5e6c-8394-a6493742b3eb","text":"To ensure no service can fail","isCorrect":false,"position":2},{"id":"174df4f4-4f21-5e64-9bbc-688701250464","text":"To avoid all network communication","isCorrect":false,"position":3}]},{"id":"b32d4a04-57ff-5636-b219-cb64ae9bea5a","position":185,"prompt":"Which scenario best demonstrates augmented reality?","explanation":"The arrows digitally augment the user's view of the physical environment.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"d78f3b395a06dfe708faaf4289b16c9c6bdc6943a9539adeb97612668da29d04","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"7a191a01-1bc7-58cc-95b0-b684685f3cc6","text":"A headset replaces the room with a virtual planet","isCorrect":false,"position":0},{"id":"d6c26c4c-1c9f-5354-90f7-36fef6b4b3bd","text":"A printer produces a report","isCorrect":false,"position":1},{"id":"69b8d6be-d924-5bb0-ab5b-ef1e4eddc33e","text":"A database sorts names","isCorrect":false,"position":2},{"id":"2d87edc1-a302-5372-ad48-11e51899f397","text":"A phone shows navigation arrows over the live street view","isCorrect":true,"position":3}]},{"id":"38e8818e-c7bc-5adf-839f-57df90b8ce20","position":186,"prompt":"Which scenario best demonstrates virtual reality?","explanation":"VR creates an immersive simulated setting for interaction or training.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"df1666900827d43893ab1bec803efc6a23c55d40f6ef602f4828ed32a974fe2d","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"17aaec7f-e084-50b3-b002-d5b5fa72b64e","text":"A spreadsheet highlights a cell","isCorrect":false,"position":0},{"id":"c319c466-d537-5dc4-be20-8d446bea798f","text":"A sensor sends temperature data","isCorrect":false,"position":1},{"id":"d44828de-72a0-50ac-8d9e-16931e66b484","text":"A headset places a trainee inside a simulated operating room","isCorrect":true,"position":2},{"id":"b559608b-5e34-59a4-a55a-efd075dbf1c8","text":"A camera labels a real machine part","isCorrect":false,"position":3}]},{"id":"d695d70d-3349-5179-8b13-63f95a4fa28b","position":187,"prompt":"What does extended reality, or XR, encompass?","explanation":"XR is an umbrella term for technologies that blend or replace perceived reality with digital content.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"d046c9d315739f70da02ba61bb9eb48112f6c5f41ebe8a35a49570f7868055fc","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"799a28a1-94ed-5ea9-aa03-b8d1d658b53a","text":"Only physical robots","isCorrect":false,"position":0},{"id":"bab4aaad-3c51-5b7d-8bad-edd19a360dfe","text":"Virtual, augmented and mixed-reality technologies","isCorrect":true,"position":1},{"id":"1cce7fc4-ff35-5e4b-b168-131350be5ddf","text":"Only text messaging","isCorrect":false,"position":2},{"id":"3d626764-8fa4-5982-870b-58702d45edf5","text":"Only quantum computing","isCorrect":false,"position":3}]},{"id":"a8f78137-2d16-597d-9e14-28bee5d57f09","position":188,"prompt":"How can XR improve remote collaboration?","explanation":"Shared virtual spaces can add spatial and interactive cues beyond ordinary calls.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"36d476dd80bf4ddab771c1ab4f1a7323fad5a62ae69e4ea28e4d3c538cb0130d","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"8a40b351-8568-54b5-ab74-ca050e215033","text":"It can give distributed participants a shared immersive workspace","isCorrect":true,"position":0},{"id":"01c19c88-7ca2-54f3-afa6-7833738fb01f","text":"It makes network connections unnecessary","isCorrect":false,"position":1},{"id":"b8db671f-ab6b-5a22-9eef-20b09777d0e2","text":"It prevents visual interaction","isCorrect":false,"position":2},{"id":"e9ef2234-3c74-541a-9938-7c7d737f72bf","text":"It converts meetings into printed output only","isCorrect":false,"position":3}]},{"id":"b02b7f42-afa3-59d7-9d34-a76535e16466","position":189,"prompt":"Why is simulation useful for professional training?","explanation":"Simulation supports repeatable practice while limiting risk to people and equipment.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"f8f9c5db32568eb2ab77c92218b2972177188914a68bb23fa2915bca220264f9","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"1a4e540e-48f8-5aa5-9d1b-48055512284e","text":"It guarantees expertise without feedback","isCorrect":false,"position":0},{"id":"2575a58e-3c95-53d6-8a9b-9fec196eaeb6","text":"It removes the need for realistic scenarios","isCorrect":false,"position":1},{"id":"a3206fff-c10c-5911-b477-84a48982cdb7","text":"It makes every error physically dangerous","isCorrect":false,"position":2},{"id":"aa398134-0d16-5fc1-a57b-e700d82d69b9","text":"Learners can practise difficult or hazardous tasks in a controlled environment","isCorrect":true,"position":3}]},{"id":"3956c6a3-75e1-506d-993d-6abf525ac0ef","position":190,"prompt":"How can robotics assist agriculture?","explanation":"Agricultural robots and drones can gather data and assist targeted monitoring or treatment.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"33f60df34c06fc9d6e301826ef32c2119091d370d97dbb29d10bc0ea7b3ab1e7","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"557c4e9f-7aa6-5cf0-809f-1cf8edb08088","text":"Drones can operate without data","isCorrect":false,"position":0},{"id":"5f9b4c8d-81bb-54f5-bf5d-fb795c0ba01b","text":"Machine learning replaces soil and weather","isCorrect":false,"position":1},{"id":"0413571e-66e2-5064-bbb9-37efcf8f2008","text":"Sensors and autonomous machines can monitor crops and support field operations","isCorrect":true,"position":2},{"id":"6167901a-3916-5873-9b93-d7933888550e","text":"Robots eliminate the need for all agronomic knowledge","isCorrect":false,"position":3}]},{"id":"686efacd-f32a-5e7d-ab9f-124bca0a232c","position":191,"prompt":"Why do autonomous systems combine sensors with processing algorithms?","explanation":"Autonomy depends on perception, computation and controlled action working together.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"5c00f428b11c81413622a46373042eeb0480852288b82939700837e5d0290a19","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"428cd386-7399-5233-8286-0cc99d97f336","text":"Neither component affects decisions","isCorrect":false,"position":0},{"id":"1d88730e-882d-5812-81b1-dc00d6b78aa7","text":"Sensors observe conditions while algorithms interpret them and select actions","isCorrect":true,"position":1},{"id":"c6ecb88c-1238-5da8-a01e-62ff37aadb1e","text":"Sensors make computation unnecessary","isCorrect":false,"position":2},{"id":"1a4ab77b-7c73-59db-9e06-f90ce6c4b7fb","text":"Algorithms physically measure every signal","isCorrect":false,"position":3}]},{"id":"cdef6348-b06b-5170-90c8-e62778df8bf9","position":192,"prompt":"Why is it misleading to say quantum computers will make every calculation exponentially faster?","explanation":"Quantum speedups are problem-specific and require suitable algorithms and practical hardware.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Emerging Technologies and the Future of Computing","fingerprint":"5e77e99cdfd3f44539878c6a45a94dbbfa4b23d53272e69d239695415a4789e0","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"1736c781-1cdb-5ee1-b131-da6f0d4de25f","text":"Quantum advantage applies to particular algorithms and problems, not all workloads","isCorrect":true,"position":0},{"id":"4ff1cc92-70a1-5003-96bf-9aa37b1c2bea","text":"Quantum computers contain no mathematics","isCorrect":false,"position":1},{"id":"06136a3a-4726-5849-a0b3-9f15ea42d816","text":"Classical computers cannot perform any calculation","isCorrect":false,"position":2},{"id":"fde12b63-1f36-599e-92fa-bbc69b133c46","text":"Every qubit is a conventional hard disk","isCorrect":false,"position":3}]},{"id":"4992553d-b78b-58df-b47e-e00b8c7c1034","position":193,"prompt":"A self-driving vehicle must react immediately but also contribute data to long-term fleet analysis. Which architecture is best?","explanation":"A hybrid edge-cloud design combines low-latency local decisions with scalable central learning and storage.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Emerging Technologies and the Future of Computing","fingerprint":"69cb2ae6871b36436f9d20cf60e1f6795ec9ba385eb3581c5be08ffa90a76a3e","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"23832066-a8b1-5358-81bf-05e87266f5a4","text":"Send every urgent decision to a distant server only","isCorrect":false,"position":0},{"id":"2710c34c-e9ec-5943-b6b7-0188827dbcbe","text":"Remove local sensors","isCorrect":false,"position":1},{"id":"52bf9d71-75c7-5a80-8245-bc2016651d10","text":"Store all driving data on paper","isCorrect":false,"position":2},{"id":"0a2c1148-63d0-5db9-819c-5939ee17c71c","text":"Use edge processing for immediate control and cloud systems for aggregated analysis","isCorrect":true,"position":3}]},{"id":"3028fd4d-f28f-5f80-b600-58a4dd094343","position":194,"prompt":"An XR training system causes motion sickness and excludes users with visual impairments. What should the team do?","explanation":"Emerging technology should be evaluated for usability, safety and inclusive access.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Emerging Technologies and the Future of Computing","fingerprint":"289a1a0562265be841cdc9ac2e2ebad39f1d5064f4fa346ca345b9b82a16e452","studyRef":{"sourceLabel":"COS 101 lecture note, Module Eight","sourceKind":"supplied_material","reviewedFromLocalFile":true},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"COS 101 lecture note, Module Eight","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"0b4ea602-d86f-5144-98b0-63d344ec706e","text":"Remove all user feedback","isCorrect":false,"position":0},{"id":"95088114-51e0-5c1f-8c44-1aff2a843da0","text":"Increase motion without testing","isCorrect":false,"position":1},{"id":"77f7b4a2-3e26-5d4b-9044-2d1230a23c2d","text":"Redesign with comfort settings, alternative modes and accessibility testing","isCorrect":true,"position":2},{"id":"be08ec53-b3fa-5bc4-aa2e-05998e3b72db","text":"Require every user to tolerate the same interface","isCorrect":false,"position":3}]},{"id":"0bc039c3-5fe3-59d3-9b83-21f123e6ac2d","position":195,"prompt":"What is machine learning?","explanation":"Machine-learning algorithms estimate useful patterns from examples rather than relying only on fixed hand-written rules.","questionKind":"concept","difficulty":"easy","cognitive":"recall","topic":"Emerging Technologies and the Future of Computing","fingerprint":"6f31f543d69e1fb11cd9215141763fb350d8e22a2eb426526b97487a01664ddd","studyRef":{"sourceLabel":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","sourceKind":"general_cos101","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"1a9112d7-2c0e-5867-86da-2f4f28d88346","text":"A type of power supply","isCorrect":false,"position":0},{"id":"e544d630-41ee-5675-a8a5-7a3d0f3983dc","text":"A method that enables systems to learn patterns from data for predictions or decisions","isCorrect":true,"position":1},{"id":"4a1fff25-44c5-5443-b479-a2962844cdc3","text":"A mechanical method for printing books","isCorrect":false,"position":2},{"id":"1a719c2d-f52e-5230-9bbe-aa1495f7fc39","text":"A guarantee that computers understand every result","isCorrect":false,"position":3}]},{"id":"5f0806ab-789f-5550-b851-883d22011e45","position":196,"prompt":"How does automation differ from artificial intelligence?","explanation":"A workflow can be automated with fixed rules; AI is one possible component for tasks requiring inference.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"f0aac8a48ae7379e5ebb6beca14a03393249ae89d956a8aebaeba529ae18bea2","studyRef":{"sourceLabel":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","sourceKind":"general_cos101","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"b69efa5d-2e84-565d-823e-2ccc184d4126","text":"Automation follows a process, while AI may infer patterns or adapt decisions","isCorrect":true,"position":0},{"id":"f4913b7b-8659-5c99-9237-431a1fabc3b3","text":"Automation always requires consciousness","isCorrect":false,"position":1},{"id":"ab4f2311-bc82-59d9-8783-bfcc506e6190","text":"AI cannot be used in automation","isCorrect":false,"position":2},{"id":"090ee015-0497-5c96-8f03-78b91a05edfa","text":"They both mean replacing all workers","isCorrect":false,"position":3}]},{"id":"e91f5feb-11ca-5bc9-a963-68946e02a13f","position":197,"prompt":"Why does the energy efficiency of computing infrastructure matter?","explanation":"Efficient devices, software and data centres can reduce energy use, cost and environmental impact.","questionKind":"application","difficulty":"medium","cognitive":"application","topic":"Emerging Technologies and the Future of Computing","fingerprint":"993c3112791ca7ddd7d0dddaa9895896a7866b1e514c86e93cbecca035ec4fd9","studyRef":{"sourceLabel":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","sourceKind":"general_cos101","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"64bd4bf5-fdc4-5c2d-af48-f2017feb2701","text":"Electricity never affects computing","isCorrect":false,"position":0},{"id":"175d14db-9d8c-5c43-8c19-57fe8feaefbf","text":"Efficient hardware stores no data","isCorrect":false,"position":1},{"id":"c9b16d36-3b98-50b5-ab62-d1d4c805457c","text":"Only paper systems use energy","isCorrect":false,"position":2},{"id":"33245e83-711b-5022-b979-beae07a9d403","text":"Computing consumes resources and has financial and environmental costs","isCorrect":true,"position":3}]},{"id":"156e1760-3292-5fee-957e-e45325e2f6e5","position":198,"prompt":"A medical AI was trained on patients from one region and performs poorly elsewhere. What is the best response?","explanation":"Model validity depends on relevant data and measured performance for the populations where it is used.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Emerging Technologies and the Future of Computing","fingerprint":"5919c79c54fd512a7c609d0dac24af385ed9acecd388d198dd67521a653d30f5","studyRef":{"sourceLabel":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","sourceKind":"general_cos101","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"f89c176e-2edf-5e88-9241-ccc8376ba5a5","text":"Hide the performance difference","isCorrect":false,"position":0},{"id":"4b61ac3a-caaa-5cd6-8893-3709d7ad8973","text":"Remove clinical oversight","isCorrect":false,"position":1},{"id":"c7fadd31-e2be-57f2-b307-1f021f036cfd","text":"Evaluate representativeness, retrain with appropriate data and monitor subgroup performance","isCorrect":true,"position":2},{"id":"83d21734-d02f-5496-9fc9-24e7850e8310","text":"Assume one dataset represents everyone","isCorrect":false,"position":3}]},{"id":"0454613a-01c4-53d7-bdf8-95e9bd121b62","position":199,"prompt":"An autonomous system faces a high-stakes situation outside its training experience. Which safeguard is strongest?","explanation":"High-stakes automation needs bounded behaviour, monitoring and a safe path when confidence or conditions are inadequate.","questionKind":"application","difficulty":"hard","cognitive":"analysis","topic":"Emerging Technologies and the Future of Computing","fingerprint":"121051e69af8b9ab4aed4dd0d1b35b97f1f83d2fb15316cc5980677723b0ede8","studyRef":{"sourceLabel":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","sourceKind":"general_cos101","reviewedFromLocalFile":false},"generationMeta":{"import":"codex_cos101_200_v1","sourceReference":"General COS 101 enrichment: Emerging Technologies and the Future of Computing","technicalAccuracyReviewCompleted":true,"humanVerificationRequired":true},"options":[{"id":"80588890-9246-5ac9-a635-364dc239fa12","text":"Disable emergency controls","isCorrect":false,"position":0},{"id":"408535b7-6574-5a13-b2c0-2dd136de88b1","text":"Detect uncertainty and escalate to an accountable human or safe fallback","isCorrect":true,"position":1},{"id":"3ce72c3d-659e-5625-a90a-df6f30edd1e6","text":"Act confidently without limits","isCorrect":false,"position":2},{"id":"ebf507e1-42d7-5d35-a5d8-6166885f0495","text":"Delete all system logs","isCorrect":false,"position":3}]}]$cos101_questions$::jsonb)
  LOOP
    INSERT INTO public.study_quiz_questions
      (id, set_id, prompt, explanation, question_type, position, question_kind,
       difficulty_level, cognitive_level, source_topic, question_fingerprint,
       study_ref, generation_meta, ai_generated, published, created_at)
    VALUES
      ((v_question->>'id')::uuid, v_set_id, v_question->>'prompt', v_question->>'explanation',
       'mcq', (v_question->>'position')::integer, v_question->>'questionKind',
       v_question->>'difficulty', v_question->>'cognitive', v_question->>'topic',
       v_question->>'fingerprint', v_question->'studyRef', v_question->'generationMeta',
       false, true, now());

    FOR v_option IN
      SELECT value FROM jsonb_array_elements(v_question->'options')
    LOOP
      INSERT INTO public.study_quiz_options
        (id, question_id, text, is_correct, position, created_at)
      VALUES
        ((v_option->>'id')::uuid, (v_question->>'id')::uuid, v_option->>'text',
         (v_option->>'isCorrect')::boolean, (v_option->>'position')::integer, now());
    END LOOP;
  END LOOP;

  UPDATE public.study_quiz_sets
  SET questions_count = 200,
      exam_question_count = 40,
      time_limit_minutes = 40,
      published = false,
      visibility = 'private',
      updated_at = now()
  WHERE id = v_set_id;
END
$import$;

COMMIT;

-- Expected: 200 questions, 800 options, 200 correct options, 0 verified before admin review.
SELECT
  s.id AS set_id,
  s.title,
  count(DISTINCT q.id) AS questions,
  count(o.id) AS options,
  count(o.id) FILTER (WHERE o.is_correct) AS correct_options,
  count(DISTINCT q.id) FILTER (WHERE q.exam_verified_at IS NOT NULL) AS verified_questions
FROM public.study_quiz_sets s
LEFT JOIN public.study_quiz_questions q ON coalesce(q.set_id, q.quiz_set_id) = s.id
LEFT JOIN public.study_quiz_options o ON o.question_id = q.id
WHERE upper(regexp_replace(coalesce(s.course_code, ''), '[^A-Za-z0-9]', '', 'g')) = 'COS101'
  AND s.delivery_mode = 'mock_exam'
  AND s.exam_campaign_key = 'supplementary-2026'
GROUP BY s.id, s.title;
